'use strict';
const CA=ContextAssist;
function assistState(d){if(!d.assist)d.assist={text:'',files:[],candidates:[],issues:[],history:[]};return d.assist;}
function entryContext(){
  const d=entryDraft(),a=assistState(d),f=d.fields;
  const required=[['supplier','Fornecedor / exportador'],['direction','Direção'],['modal','Modal'],['origin','Origem'],['destination','Destino'],['incoterm','Incoterm'],['incotermVersion','Versão do Incoterm'],['namedPlace','Local nomeado'],['contractor','Quem contrata o frete'],['owner','Responsável interno pela auditoria']];
  const missing=required.filter(([key])=>!String(f[key]||'').trim());
  const choices={direction:['Importação','Exportação'],modal:['Marítimo FCL','Marítimo LCL','Aéreo','Rodoviário','Multimodal'],incoterm:['EXW','FCA','FAS','FOB','CFR','CIF','CPT','CIP','DAP','DPU','DDP','NA'],contractor:['Vendedor / exportador','Comprador / cliente','Cliente exportador','Terceiro']};
  const source=key=>d.contextTrace?.[key]?.source||'Já presente no rascunho';
  return `<section class="panel context-assistant"><div class="panel-head"><div><h2>Monte o contexto com ajuda da IA</h2><p class="small muted">Aproveite os registros e traga a mensagem ou os documentos da operação.</p></div>${badge('Demonstração','blue')}</div><div class="panel-body"><div class="assist-inputs"><label class="field">Cole uma mensagem ou o texto dos documentos<textarea id="assist-text" placeholder="Fornecedor: …&#10;Modal: …&#10;Incoterm: …&#10;Contratante: …">${esc(a.text)}</textarea></label><div class="assist-upload"><strong>Documentos para entender a operação</strong><p class="small muted">Cotação, booking, BL ou instrução recebida.</p><label class="field">Selecionar documentos<input type="file" multiple id="assist-files" accept=".pdf,.png,.jpg,.jpeg,.eml,.txt"></label><p class="small">${a.files.length?a.files.map(esc).join(' · '):'Você pode trazer as fontes antes de preencher o contexto.'}</p><p class="small muted">${a.files.length?'Arquivos identificados nesta sessão; leitura por IA pendente.':'Arquivos não são enviados nesta prévia.'}</p></div></div><div class="assist-actions">${button('Preparar sugestões','assist-prepare','','primary')}${button('Experimentar com texto de exemplo','assist-example','','text small')}</div><p class="small muted">Demonstração sem IA ou leitura real de arquivos: reconhece os campos rotulados do exemplo. No produto, a IA fará a extração e apontará fontes, incertezas e conflitos.</p></div></section>
  ${a.candidates.length||a.issues.length?`<section class="panel gap"><div class="panel-head"><h2>Revise as sugestões</h2><span class="small muted">Campos preenchidos ficam desmarcados</span></div><div class="panel-body">${a.issues.map(x=>`<p class="status-warning">${esc(x)}</p>`).join('')}<div class="assist-suggestions">${a.candidates.map((c,n)=>`<label class="assist-suggestion"><input type="checkbox" data-assist-candidate="${n}" ${c.selected?'checked':''} ${c.conflict?'disabled':''}><div><strong>${esc(c.name)}</strong><span>Atual: ${esc(c.before||'Não informado')}</span><span class="assist-value">Sugestão: ${esc(c.value)}</span><small>${esc(c.source)}${c.conflict?' · conflito; confirme manualmente':c.before?' · só será alterado se você selecionar':''}</small></div></label>`).join('')}</div>${a.candidates.length?button('Aplicar sugestões selecionadas','assist-apply','','primary'):''}</div></section>`:''}
  <section class="panel gap"><div class="panel-head"><div><h2>Contexto disponível</h2><p class="small muted">${required.length-missing.length} de ${required.length} dados essenciais preenchidos. Preenchimento não comprova validade da fonte.</p></div>${button('Atualizar resumo','assist-refresh','','text small')}</div><div class="panel-body"><dl class="assist-context-grid">${required.filter(([key])=>String(f[key]||'').trim()).map(([key,label])=>`<div><dt>${esc(label)}</dt><dd>${esc(f[key])}</dd><small>${esc(source(key))}</small></div>`).join('')||'<p>Os dados vão aparecer aqui com suas fontes. Use os documentos, o texto ou preencha somente o que faltar.</p>'}</dl>${a.history.length?`<details class="entry-secondary"><summary>Alterações aplicadas nesta revisão</summary>${a.history.map(c=>`<p>${esc(CA.fields.find(x=>x[0]===c.key)?.[1]||c.key)}: ${esc(c.before||'vazio')} → ${esc(c.value)}<br><small>${esc(c.source)}</small></p>`).join('')}</details>`:''}</div></section>
  <section class="panel gap"><div class="panel-head"><h2>${missing.length?'Só falta completar':'Confirme as responsabilidades'}</h2><span class="small muted">Revisão concentrada no necessário</span></div><div class="panel-body"><div class="form-grid">${missing.map(([key,label])=>entryInput(key,label,'text',choices[key]||null)).join('')}${!missing.some(([k])=>k==='contractor')?entryChoice('contractor','Quem contrata o frete principal?',['Vendedor / exportador','Comprador / cliente','Cliente exportador','Terceiro']):''}${entryChoice('payment','Pagamento do frete',['Prepaid','Collect','Misto','Não confirmado'])}${f.incoterm==='NA'||f.quoteOrigin==='Sem referência formal'?entryInput('absenceReason','Justificativa / fonte alternativa'):''}${f.period==='Concluída'&&!f.operationDate?entryInput('operationDate','Data original da operação','date'):''}</div><p class="small muted">Contratante e prepaid/collect são independentes do Incoterm. Dados inconclusivos podem ser salvos em rascunho.</p><label class="attachment"><input type="checkbox" data-entry-field="contextConfirmed" ${f.contextConfirmed?'checked':''}><span>Conferi o contexto e as responsabilidades.<small>As sugestões não substituem aceite comercial nem aprovam a auditoria.</small></span></label></div></section>
  ${E.duplicates(operations,d).length?'<div class="status-warning gap">Há um possível vínculo existente. Abra os dados abaixo para rever a operação ou justificar a referência compartilhada.</div>':''}
  <details class="entry-secondary assist-manual" ${E.duplicates(operations,d).length?'open':''}><summary>Editar todos os dados da operação</summary>${entryManualContext()}</details>`;
}
document.addEventListener('click',event=>{
  const b=event.target.closest('[data-action^="assist-"]');if(!b)return;event.preventDefault();const d=entryDraft(),a=assistState(d);
  if(b.dataset.action==='assist-example'){a.text=CA.example;a.inputOrigin='Texto de exemplo DEMO';const r=CA.extract(a.text,d.fields,a.inputOrigin);a.candidates=r.candidates;a.issues=r.issues;entryRender();}
  if(b.dataset.action==='assist-prepare'){const r=CA.extract(a.text,d.fields,a.inputOrigin||'Texto informado');a.candidates=r.candidates;a.issues=r.issues;if(!r.candidates.length&&!r.issues.length)a.issues=['Nenhum campo rotulado reconhecido nesta demonstração. Experimente o texto de exemplo ou complete os dados abaixo.'];entryRender();}
  if(b.dataset.action==='assist-apply'){const r=CA.apply(d);a.issues=r.skipped.length?['Campos editados depois da sugestão foram preservados: '+r.skipped.join(', ')]:[];entryRender();toast(r.applied.length?r.applied.length+' sugestões aplicadas para revisão.':r.skipped.length?'Edições mais recentes preservadas.':'Nenhuma alteração selecionada.');}
  if(b.dataset.action==='assist-refresh')entryRender();
});
document.addEventListener('input',event=>{
  const t=event.target,d=entryDraft();if(t.id==='assist-text'){assistState(d).text=t.value;assistState(d).inputOrigin='Texto informado';persist();}
  if(t.dataset.assistCandidate!==undefined){assistState(d).candidates[Number(t.dataset.assistCandidate)].selected=t.checked;persist();}
  if(t.dataset.entryField&&t.dataset.entryField!=='contextConfirmed'&&d.step===2){d.contextTrace=d.contextTrace||{};d.contextTrace[t.dataset.entryField]={source:'Informado manualmente',status:'A revisar'};d.fields.contextConfirmed=false;for(const checkbox of document.querySelectorAll('[data-entry-field="contextConfirmed"]'))checkbox.checked=false;persist();}
});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='assist-files'){const d=entryDraft(),a=assistState(d);a.files=[...new Set([...a.files,...[...t.files].map(f=>f.name)])];let s=d.sources.find(s=>s.id==='context');if(!s){s={id:'context',name:'Fontes para identificar o contexto',help:'Classificação e leitura dos documentos ainda pendentes.',status:'Pendente',files:[],reason:'',owner:'',deadline:'',linked:false};d.sources.push(s);}s.files=[...a.files];s.status=s.files.length?'Arquivo selecionado':'Pendente';entryRender();}});
